import { createHash } from 'node:crypto'
import { describe, expect, it } from 'vitest'
import { inspectHevcPps, inspectHevcSps } from '../src/codecs/hevc.ts'
import { decodeHevcIntraPicture } from '../src/codecs/hevc-picture.ts'

const bytes = (base64: string): Uint8Array => Uint8Array.from(Buffer.from(base64, 'base64'))

const pictureHash = (picture: ReturnType<typeof decodeHevcIntraPicture>): string => {
  const sampleBytes = picture.bitDepth === 10 ? 2 : 1
  const output = new Uint8Array(
    (picture.y.length + picture.u.length + picture.v.length) * sampleBytes,
  )
  const view = new DataView(output.buffer)
  let offset = 0
  for (const plane of [picture.y, picture.u, picture.v]) {
    for (const sample of plane) {
      if (sampleBytes === 1) output[offset] = sample
      else view.setUint16(offset, sample, true)
      offset += sampleBytes
    }
  }
  return createHash('sha256').update(output).digest('hex')
}

describe('restricted HEVC intra-picture reconstruction', () => {
  it('exactly reconstructs an independently encoded 8-bit 4:2:0 picture', () => {
    // Generated by x265 4.1 from a 32x32 YUV gradient with SAO, deblocking,
    // WPP, tiles, scaling lists, and CU QP deltas disabled. The expected hash
    // was produced from FFmpeg's decoded planar YUV output.
    const sps = inspectHevcSps(bytes('QgEBBAgAAAMAn6gAAAMAAB6gQghZbp5MLwFoCAAAAwAIAAADAAhA'))
    const pps = inspectHevcPps(bytes('RAHBcYGkgA=='))
    const picture = decodeHevcIntraPicture(bytes('KAGsfOk6FoCJZBiPsF7C3iika9NAeA=='), 20, {
      pps: [pps],
      sps: [sps],
    })
    expect(pictureHash(picture)).toBe(
      'ddde086a6b5565eea61390bd612d5998f358d9232a5ad9d64cf32b238ff7cc81',
    )
    expect(picture).toMatchObject({ width: 32, height: 32, bitDepth: 8, chromaFormat: 1 })
  })

  it('exactly reconstructs an independently encoded Main 10 picture', () => {
    // x265 4.1 encoded this 32x32 testsrc2 picture as limited-range Main 10
    // BT.2020/PQ. FFmpeg produced the expected little-endian planar YUV hash.
    const sps = inspectHevcSps(
      bytes('QgEBAiAAAAMAkAAAAwAAAwAeoEIITZZKuTC8BahIgEggAAADACAAAAMAIQ=='),
    )
    const pps = inspectHevcPps(bytes('RAHBcaGkgA=='))
    const picture = decodeHevcIntraPicture(
      bytes(
        '',
      ),
      20,
      { pps: [pps], sps: [sps] },
    )

    expect(pictureHash(picture)).toBe(
      'b57475d182520e92de78571f145f8921752b8dd139d01c1dfcb9d58a70f20c66',
    )
    expect(picture).toMatchObject({ width: 32, height: 32, bitDepth: 10, chromaFormat: 1 })
  })

  it('exactly reconstructs mixed 8x8 and 4x4 intra coding units', () => {
    // Generated by x265 4.1 from FFmpeg's 16x16 smptebars source at QP 27,
    // with a 16x16 CTU, 8x8 minimum CU, and in-loop filters disabled.
    const sps = inspectHevcSps(bytes('QgEBBAgAAAMAn6gAAAMAAB6giEWW6q8LwFqBAQKCAAADAAIAAAMAMhA='))
    const pps = inspectHevcPps(bytes('RAHBcYGkgA=='))
    const picture = decodeHevcIntraPicture(
      bytes(
        'KAGssGdxpL4vmOELn5LfVzBN52Gd3sqIJAWe1jhXy4qBvBNtLV3k74JomqxyI0R7zW422U3PwQ2QSCrAQDlcC6lBh9GVvtTTWmZKmov8X7nySTquNmH5UmqKL9+KWYtqCHxXFG8XSgmAurYdQtr/74wKX6QWP/8WnNZ8YxXnGuTsGwSMxIxJwCLA',
      ),
      20,
      { pps: [pps], sps: [sps] },
    )

    expect(pictureHash(picture)).toBe(
      'ba1fc796c0522b92f463d9b4867643d627c0f7987a212e5e7deb4b19e8d23e15',
    )
    expect(picture).toMatchObject({ width: 16, height: 16, bitDepth: 8, chromaFormat: 1 })
  })

  it('exactly reconstructs WPP rows with scaling lists and CU QP deltas', () => {
    // x265 4.1 encoded this 128x128 testsrc2 picture using four 32x32 CTB
    // rows, WPP entry points, default scaling lists, 8x8 quantization groups,
    // and CU QP deltas. FFmpeg produced the expected planar YUV hash.
    const sps = inspectHevcSps(bytes('QgEBAWAAAAMAkAAAAwAAAwAeoBAgIFllZrk4XgLQEAAAAwAQAAADAZCA'))
    const pps = inspectHevcPps(bytes('RAHBcvR0kA=='))
    const picture = decodeHevcIntraPicture(
      bytes(
        '',
      ),
      20,
      { pps: [pps], sps: [sps] },
    )

    expect(pictureHash(picture)).toBe(
      'b413c309b3a007953c26837f392f4398ee4ab614289ae1dbd253b77fedfe04af',
    )
    expect(picture).toMatchObject({ width: 128, height: 128, bitDepth: 8 })
  })
})
